-- SQLite import package: disaster-events
BEGIN;
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('dingwu-north-china-famine','丁戊奇荒','disaster','span',NULL,'approximate_year','approximate_year','研究常以1876—1879年概括华北大饥荒，中文“丁戊”指灾情高峰所在的1877、1878年；部分资料将旱象追溯至1875年。此处用概略区间涵盖旱灾发展与灾后缓解，不采用有争议的死亡数字。；原不确定范围：1875年1月至1879年12月；按既有事件说明转为持续区间。',NULL,NULL,NULL,NULL,1875,1,NULL,22500,1879,12,NULL,22559,'晚清华北持续旱灾引发严重饥荒，山西、河南、陕西、直隶、山东等地受灾，灾情在1877—1878年尤重，并波及邻近地区。饥荒造成粮食短缺、人口流徙和大规模赈济；不同研究对灾害起讫及死亡规模的估计不一。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('jianan-twenty-two-epidemic','建安二十二年大疫','disaster','point','year',NULL,NULL,'建安二十二年（217）；按年精度记录。史料未能证明该场疫情始于196年，也不能据此确认为鼠疫或伤寒。',217,12,NULL,2615,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'建安二十二年，北方疫病流行。曹丕次年致吴质书追述亲友多遭疫病，陈琳、徐幹、应玚、刘桢相继去世；曹植《说疫气》也记述当年疫病造成的广泛死亡。疫情影响建安文人群体，但史料不足以判定具体病原或量化死亡人数。',NULL,NULL);
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('ming-capital-epidemic-1643','京师大疫','disaster','point','year',NULL,NULL,'崇祯十六年（1643）；史籍所记二月至九月为农历，事件按年精度记录，不将农历月份直接换算为公历月份。',1643,12,NULL,19727,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'崇祯十六年，北京发生严重疫病。《明史·五行志》记京师自二月至九月大疫，明末记述亦称死亡甚众。后世研究对当时疫病是否为鼠疫仍有不同判断，现有史料不足以确认具体病原或可靠死亡总数。',NULL,NULL);
COMMIT;
